import React from 'react';
import Sidebar from './Sidebar';
import Header from './Header';

interface LayoutProps {
    children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex transition-colors duration-300">
            {/* Sidebar - Sticky on Desktop */}
            <aside className="hidden lg:block w-72 flex-shrink-0 border-r border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 z-40 sticky top-0 h-screen overflow-y-auto">
                <Sidebar />
            </aside>

            {/* Mobile Sidebar (handled internally by Sidebar component via fixed positioning) */}
            <div className="lg:hidden">
                <Sidebar />
            </div>

            {/* Main Content Area - Flex Column */}
            <main className="flex-1 flex flex-col min-w-0">
                {/* Top Header for Utility Items */}
                {/* Added padding-top on mobile to account for the fixed Mobile Menu Bar (h-16) from Sidebar.tsx */}
                <div className="pt-16 lg:pt-0 sticky top-0 z-30">
                    <Header />
                </div>

                {/* Content Area */}
                <div className="flex-1 p-4 lg:p-8">
                    {children}
                </div>
            </main>
        </div>
    );
};

export default Layout;
